mapper.select:
SELECT NVL(MAX(set_no), 0) + 1
FROM workout_sets
WHERE workout_exercise_id = #{workoutExerciseId}

mapper.delete:
DELETE FROM workout_sets
WHERE workout_set_id = #{workoutSetId}
  AND workout_exercise_id = #{workoutExerciseId}
  AND EXISTS (
      SELECT 1
      FROM workout_exercises we
      JOIN workout_logs wl
        ON wl.workout_log_id = we.workout_log_id
      WHERE we.workout_exercise_id = workout_sets.workout_exercise_id
        AND we.workout_log_id = #{workoutLogId}
        AND wl.member_id = #{memberId}
  )
